def test_index_retains_past_and_future_and_container_lifecycle(self):
    parsed=sdk_api_index.parse(b'<api version="4"><sdk id="30"/><class name="a/Old" since="1" removed="36"/><class name="a/Future" since="38"><method name="f()V" since="1"/></class><class name="a/Backport" since="34" sdks="30:4,0:34"/></api>',target='37.2')
    rows={r['canonical']:r for r in parsed['records']}
    self.assertIn('a/Old',rows);self.assertIn('a/Future#f()V',rows)
    self.assertEqual(rows['a/Future#f()V']['extras']['container_api_lifecycle']['since'],'38')
    self.assertEqual(rows['a/Backport']['extras']['sdk_extensions'],[{'sdk_id':'30','minimum_version':'4'},{'sdk_id':'0','minimum_version':'34'}])

 def test_package_and_type_have_distinct_identity_namespaces(self):
  with tempfile.TemporaryDirectory() as td:
   r=pathlib.Path(td);inv=self.fixture(r);data=json.loads(inv.read_text());s=data['sources'][0];raw=((r/'api.txt').read_text()+'
package a {
 public class B {
 method public void x();
 }
}
package a.B {
 public class C {
 method public void y();
 }
}
').encode();(r/'api.txt').write_bytes(raw);s.update(sha256=hashlib.sha256(raw).hexdigest(),git_blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest(),size_bytes=len(raw));inv.write_text(json.dumps(data));b.build(inv,r/'out')
   db=sqlite3.connect(r/'out/catalog.sqlite');self.addCleanup(db.close)
   type_id=db.execute("SELECT binding_id FROM bindings WHERE signature='java:a.B' AND kind='class'").fetchone()[0]
   package_id=db.execute("SELECT binding_id FROM bindings WHERE signature='java:package:a.B' AND kind='package'").fetchone()[0]
   self.assertNotEqual(type_id,package_id)

